<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{data:any;active?:boolean;printOnly?:boolean}>();
const fields=computed(()=>props.data.campaign.campaign_type==='inventory'?[['has_external_inventory_company','外盤公司'],['planned_inventory_time','預計盤點時間'],['inventory_staff','盤點組人員'],['notes','備註']]:[['outdoor_vendor','外場廠商'],['red_bean_cake','紅豆餅／雞蛋糕'],['circulation','循環'],['quantum','量子'],['bone_density','骨密'],['supervisor','督導'],['manager','經理'],['tasting','試飲'],['activity_team','活動組'],...Array.from({length:6},(_,i)=>['sales'+(i+1),'業務 '+(i+1)]),['indoor_pt1','內場工讀 1'],['indoor_pt2','內場工讀 2'],['notes','備註']]);
const rows=computed(()=>[...props.data.schedules].sort((a,b)=>a.activity_date.localeCompare(b.activity_date)||(a.store?.store_code||'').localeCompare(b.store?.store_code||'')).map(s=>({...s,detail:props.data.plan.details?.find((d:any)=>d.store_id===s.store_id)})));
function print(){if(props.active&&!props.data.plan.errors?.details)window.print();}
</script>
<template><div :class="printOnly?'campaign-print-sheet':'campaign-preview'"><div v-if="!printOnly" class="toolbar"><p>共 {{rows.length}} 間門市，已填 {{rows.filter(r=>r.detail).length}} 間，待填 {{rows.filter(r=>!r.detail).length}} 間</p><button :disabled="!active||!!data.plan.errors?.details" @click="print">列印／匯出 PDF</button></div><p v-if="data.plan.errors?.details" role="alert">門市細節尚未完整載入，請重新讀取後列印。</p><div v-else class="table-wrap"><table><caption>{{data.campaign.name}} · 門市細節預覽表</caption><thead><tr><th>日期</th><th>門市</th><th v-for="f in fields">{{f[1]}}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.store_id"><td>{{r.activity_date}}</td><td>{{r.store?.store_code}} {{r.store?.store_name}}</td><td v-for="f in fields">{{r.detail?.[f[0]]||'—'}}</td></tr></tbody></table></div></div><Teleport v-if="active&&!printOnly" to="body"><div class="campaign-print-output"><CampaignPreviewTable :data="data" print-only/></div></Teleport></template>
<style scoped>.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.table-wrap{max-width:100%;overflow:auto}table{border-collapse:collapse;min-width:1100px;width:100%;font-size:12px}td,th{border:1px solid var(--line,#aaa);padding:8px;vertical-align:top;white-space:pre-wrap;min-width:75px}caption{font-weight:700;font-size:17px;padding:16px}th{background:var(--surface,#f2f3ed)}</style>
<style>.campaign-print-output{display:none}@media print{@page campaign{size:A3 landscape;margin:10mm}body:has(>.campaign-print-output)>*:not(.campaign-print-output){display:none!important}body:has(>.campaign-print-output){height:auto!important;overflow:visible!important;background:white!important}.campaign-print-output{display:block!important;page:campaign;color:black;background:white}.campaign-print-output .table-wrap{overflow:visible}.campaign-print-output table{min-width:0!important;width:100%!important;table-layout:fixed;font-size:8pt}.campaign-print-output th,.campaign-print-output td{min-width:0;padding:4px;border-color:#aaa;overflow-wrap:anywhere}.campaign-print-output tr{break-inside:avoid}.campaign-print-output thead{display:table-header-group}}</style>
